213	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
214	    }
215	
216	    @Transactional
217	    public SheetRole setRole(String sheetId, String by, String user, Role role) {
218	        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
219	        SheetRole given = roles.findBySheetIdAndUser(sheetId, user).orElse(null);
220	        if (given == null) {
221	            given = roles.saveAndFlush(new SheetRole(sheetId, user, role));
222	        } else {
223	            given.setRole(role);
224	            roles.flush();
225	        }
226	        audit.change("ROLE_SET", sheetId, by, "user=" + user, "role=" + role.name().toLowerCase());
227	        return given;
228	    }
229	
230	    /** The sheet's clerk limit; null when there is none. */
231	    @Transactional(readOnly = true)
232	    public BigDecimal clerkLimit(String sheetId) {
233	        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
234	    }
235	
236	    /** Set the sheet's clerk limit; null removes it. */
237	    @Transactional
