239	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
240	        sheet.setClerkLimit(limit);
241	        sheets.flush();
242	        audit.change("SETTING_CHANGED", sheetId, by, "key=clerk-limit",
243	                "value=" + (limit == null ? "" : limit.toPlainString()));
244	        return sheet;
245	    }
246	
247	    /** The sheet's floor. */
248	    @Transactional(readOnly = true)
249	    public BigDecimal floor(String sheetId) {
250	        return sheets.findById(sheetId).map(Sheet::getFloor).orElseThrow(SheetNotFoundException::new);
251	    }
252	
253	    /** Set the sheet's floor; the live dues, and so the figures, follow it. */
254	    @Transactional
255	    public Sheet setFloor(String sheetId, String by, BigDecimal floor) {
256	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
