275	        sheet.setTerms(terms);
276	        sheets.flush();
277	        audit.change("SETTING_CHANGED", sheetId, by, "key=terms", "value=" + terms);
278	        return sheet;
279	    }
280	
281	    /** The sheet's late percent. */
282	    @Transactional(readOnly = true)
283	    public BigDecimal latePct(String sheetId) {
284	        return sheets.findById(sheetId).map(Sheet::getLatePct).orElseThrow(SheetNotFoundException::new);
285	    }
286	
287	    /** Set the sheet's late percent; the late charges, and so the figures, follow it. */
288	    @Transactional
289	    public Sheet setLatePct(String sheetId, String by, BigDecimal latePct) {
290	        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
291	        RollupService.Snapshot before = rollup.snapshot(sheetId);
292	        sheet.setLatePct(latePct);
293	        sheets.flush();
294	        audit.change("SETTING_CHANGED", sheetId, by, "key=late-pct", "value=" + latePct.toPlainString());
295	        rollup.recordSince(sheetId, by, before);
296	        return sheet;
297	    }
