300	    @Transactional(readOnly = true)
301	    public LocalDate policyDate(String sheetId) {
302	        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).getPolicyDate();
303	    }
304	
305	    /** Set the sheet's policy date; null makes it the sheet's today. The live figures' rounding follows it. */
306	    @Transactional
