413	          In force: <span data-testid="setting-policy-date-current">{{ policyDate() ?? '' }}</span>
414	          @if (policyDate() === null) {
415	            (the sheet's today)
416	          }
417	        </span>
418	        <label for="setting-period-numbering-from">Period numbering from</label>
419	        <input
420	          id="setting-period-numbering-from"
421	          data-testid="setting-period-numbering-from"
422	          type="date"
423	          [value]="periodNumberingFromInput()"
424	          (input)="periodNumberingFromInput.set(value($event)); periodNumberingFromChanged = true; settingsError.set(null)"
425	          (keydown)="periodNumberingFromChanged = true"
426	        />
427	        <span>
428	          In force: <span data-testid="setting-period-numbering-from-current">{{ periodNumberingFrom() ?? '' }}</span>
429	          @if (periodNumberingFrom() === null) {
430	            (off)
431	          }
432	        </span>
433	        <button type="submit" data-testid="settings-save">Save settings</button>
434	        @if (settingsError(); as message) {
435	          <p role="alert" class="error" data-testid="settings-error">{{ message }}</p>
436	        }
437	      </form>
438	
439	      <form (submit)="saveRole($event)" aria-label="Role" data-testid="role-form">
440	        <label for="role-form-user">User</label>
441	        <input
442	          id="role-form-user"
443	          data-testid="role-form-user"
444	          [value]="roleUser()"
445	          (input)="roleUser.set(value($event)); roleError.set(null)"
446	        />
447	        <label for="role-form-role">Role</label>
448	        <input
449	          id="role-form-role"
450	          data-testid="role-form-role"
451	          list="role-form-roles"
452	          [value]="role()"
453	          (input)="role.set(value($event)); roleError.set(null)"
454	        />
455	        <datalist id="role-form-roles">
456	          @for (r of roles; track r) {
457	            <option [value]="r"></option>
458	          }
459	        </datalist>
460	        <button type="submit" data-testid="role-form-submit">Set role</button>
461	        @if (roleError(); as message) {
462	          <p role="alert" class="error" data-testid="role-form-error">{{ message }}</p>
463	        }
464	      </form>
465	      @if (given().length > 0) {
466	        <table data-testid="role-list">
467	          <caption>Roles (anyone else is a clerk)</caption>
468	          <thead>
469	            <tr>
470	              <th scope="col">User</th>
471	              <th scope="col">Role</th>
472	            </tr>
473	          </thead>
474	          <tbody>
475	            @for (r of given(); track r.user) {
476	              <tr [attr.data-testid]="'role-row-' + r.user">
477	                <td data-testid="role-user">{{ r.user }}</td>
478	                <td data-testid="role-value">{{ r.role }}</td>
479	              </tr>
480	            }
481	          </tbody>
482	        </table>
483	      }
484	    </section>
485	  `,
486	  styles: `
487	    form {
488	      display: flex;
489	      flex-wrap: wrap;
490	      gap: 0.5rem;
491	      align-items: center;
492	      margin-bottom: 0.5rem;
493	    }
494	    .error {
495	      color: #a40000;
496	      margin: 0;
497	    }
498	    table {
499	      border-collapse: collapse;
500	      margin-bottom: 1rem;
501	    }
502	    caption {
503	      text-align: left;
504	      font-weight: bold;
505	    }
506	    th,
507	    td {
508	      text-align: left;
509	      padding: 0.25rem 0.75rem 0.25rem 0;
510	    }
511	  `,
512	})
513	export class Settings {
514	  private readonly session = inject(Session);
515	  private readonly service = inject(SettingsService);
516	
517	  protected readonly roles = ROLES;
518	  /** The clerk limit in force; null when there is none. */
519	  protected readonly clerkLimit = signal<string | null>(null);
520	  /** The floor in force, with two decimals; empty until read. */
521	  protected readonly floor = signal('');
522	  protected readonly given = signal<RoleGiven[]>([]);
523	  /** The terms in force, in days, as text; empty until read. */
524	  protected readonly terms = signal('');
525	  /** The late percent in force, with two decimals; empty until read. */
526	  protected readonly latePct = signal('');
527	  /** The floor saved, in cents. */
528	  readonly floorSaved = output<number>();
529	  /** The terms saved, in days. */
530	  readonly termsSaved = output<number>();
531	  /** The late percent saved, with two decimals. */
532	  readonly latePctSaved = output<string>();
533	  /** The policy date as set; null when it is the sheet's today. */
534	  protected readonly policyDate = signal<string | null>(null);
535	  /** The policy date saved; null when it is the sheet's today. */
536	  readonly policyDateSaved = output<string | null>();
537	
538	  /** The period numbering from date as set; null when it is off. */
539	  protected readonly periodNumberingFrom = signal<string | null>(null);
540	
541	  protected readonly limit = signal('');
542	  protected readonly floorInput = signal('');
543	  protected readonly termsInput = signal('');
544	  protected readonly latePctInput = signal('');
545	  protected readonly policyDateInput = signal('');
546	  protected readonly periodNumberingFromInput = signal('');
547	  /** Whether each field was typed in (a key pressed in it, even one that left its value as it was)
548	   *  since the settings were last loaded or saved; a field is saved when it was, or when it differs
549	   *  from the value in force. */
550	  protected limitChanged = false;
551	  protected floorChanged = false;
552	  protected termsChanged = false;
553	  protected latePctChanged = false;
554	  protected policyDateChanged = false;
555	  protected periodNumberingFromChanged = false;
556	  protected readonly settingsError = signal<string | null>(null);
557	  protected readonly roleUser = signal('');
558	  protected readonly role = signal('');
559	  protected readonly roleError = signal<string | null>(null);
560	  /** A submit is waiting for its answer; another submit of the same form meanwhile is ignored. */
561	  private savingSettings = false;
562	  /** A settings submit came while one was waiting; it is made once that one is answered. */
563	  private settingsResubmit = false;
564	  private savingRole = false;
565	
566	  constructor() {
567	    effect(() => {
568	      const sheet = this.session.sheetId();
569	      this.session.loads();
570	      this.clerkLimit.set(null);
571	      this.floor.set('');
572	      this.given.set([]);
573	      this.limit.set('');
574	      this.floorInput.set('');
575	      this.terms.set('');
576	      this.termsInput.set('');
577	      this.limitChanged = false;
578	      this.floorChanged = false;
579	      this.termsChanged = false;
580	      this.latePct.set('');
581	      this.latePctInput.set('');
582	      this.latePctChanged = false;
583	      this.policyDate.set(null);
584	      this.policyDateInput.set('');
585	      this.policyDateChanged = false;
586	      this.periodNumberingFrom.set(null);
587	      this.periodNumberingFromInput.set('');
588	      this.periodNumberingFromChanged = false;
589	      this.settingsError.set(null);
590	      this.roleUser.set('');
591	      this.role.set('');
592	      this.roleError.set(null);
593	      if (sheet) void this.read(sheet);
594	    });
595	  }
596	
597	  protected value(event: Event): string {
598	    return (event.target as HTMLInputElement).value;
599	  }
600	
601	  protected async saveSettings(event: Event): Promise<void> {
602	    event.preventDefault();
603	    if (this.savingSettings) {
604	      this.settingsResubmit = true;
605	      return;
606	    }
607	    this.settingsError.set(null);
608	    const sheet = this.session.sheetId();
609	    if (!sheet) return;
610	    const limit = this.limit().trim();
611	    const floor = this.floorInput().trim();
612	    const saveLimit = this.limitChanged || limit !== (this.clerkLimit() ?? '');
613	    const saveFloor = this.floorChanged || floor !== this.floor();
614	    const terms = this.termsInput().trim();
615	    const saveTerms = this.termsChanged || terms !== this.terms();
616	    const latePct = this.latePctInput().trim();
617	    const saveLatePct = this.latePctChanged || latePct !== this.latePct();
618	    const policyDate = this.policyDateInput().trim();
619	    const savePolicyDate = this.policyDateChanged || policyDate !== (this.policyDate() ?? '');
620	    const numberingFrom = this.periodNumberingFromInput().trim();
621	    const saveNumberingFrom =
622	      this.periodNumberingFromChanged || numberingFrom !== (this.periodNumberingFrom() ?? '');
623	    if (saveLimit && limit !== '' && !LIMIT.test(limit)) {
624	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
625	      return;
626	    }
627	    if (saveFloor && !LIMIT.test(floor)) {
628	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
629	      return;
630	    }
631	    if (saveTerms && !TERMS.test(terms)) {
632	      this.settingsError.set('Type terms as a whole number of days, 0 or more.');
633	      return;
634	    }
635	    if (saveLatePct && !LIMIT.test(latePct)) {
636	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
637	      return;
638	    }
639	    if (savePolicyDate && policyDate !== '' && !DATE.test(policyDate)) {
640	      this.settingsError.set('Type a policy date as YYYY-MM-DD, or leave it blank for the sheet\'s today.');
641	      return;
642	    }
643	    if (saveNumberingFrom && numberingFrom !== '' && !DATE.test(numberingFrom)) {
644	      this.settingsError.set('Type a period numbering from date as YYYY-MM-DD, or leave it blank to turn it off.');
645	      return;
646	    }
647	    this.savingSettings = true;
648	    try {
649	      if (saveLimit) {
650	        const settings = await this.service.setClerkLimit(sheet, limit || null);
651	        if (this.session.sheetId() !== sheet) return;
652	        if (this.limit().trim() === limit) this.limitChanged = false;
653	        this.show(settings);
654	      }
655	      if (saveFloor) {
656	        const settings = await this.service.setFloor(sheet, floor);
657	        if (this.session.sheetId() !== sheet) return;
658	        if (this.floorInput().trim() === floor) this.floorChanged = false;
659	        this.show(settings);
660	        this.floorSaved.emit(cents(settings.floor));
661	      }
662	      if (saveTerms) {
663	        const settings = await this.service.setTerms(sheet, terms);
664	        if (this.session.sheetId() !== sheet) return;
665	        if (this.termsInput().trim() === terms) this.termsChanged = false;
666	        this.show(settings);
667	        this.termsSaved.emit(settings.terms);
668	      }
669	      if (saveLatePct) {
670	        const settings = await this.service.setLatePct(sheet, latePct);
671	        if (this.session.sheetId() !== sheet) return;
672	        if (this.latePctInput().trim() === latePct) this.latePctChanged = false;
673	        this.show(settings);
674	        this.latePctSaved.emit(settings.latePct);
675	      }
676	      if (savePolicyDate) {
677	        const settings = await this.service.setPolicyDate(sheet, policyDate || null);
678	        if (this.session.sheetId() !== sheet) return;
679	        if (this.policyDateInput().trim() === policyDate) this.policyDateChanged = false;
680	        this.show(settings);
681	        this.policyDateSaved.emit(settings.policyDate);
682	      }
683	      if (saveNumberingFrom) {
684	        const settings = await this.service.setPeriodNumberingFrom(sheet, numberingFrom || null);
685	        if (this.session.sheetId() !== sheet) return;
686	        if (this.periodNumberingFromInput().trim() === numberingFrom) this.periodNumberingFromChanged = false;
687	        this.show(settings);
688	      }
689	      // Show what is in force in each field, but keep what was typed in one while the save was waiting.
690	      if (!this.limitChanged) this.limit.set(this.clerkLimit() ?? '');
691	      if (!this.floorChanged) this.floorInput.set(this.floor());
692	      if (!this.termsChanged) this.termsInput.set(this.terms());
693	      if (!this.latePctChanged) this.latePctInput.set(this.latePct());
694	      if (!this.policyDateChanged) this.policyDateInput.set(this.policyDate() ?? '');
695	      if (!this.periodNumberingFromChanged) this.periodNumberingFromInput.set(this.periodNumberingFrom() ?? '');
696	    } catch {
697	      this.settingsError.set('Those settings could not be saved.');
698	    } finally {
699	      this.savingSettings = false;
700	      if (this.settingsResubmit) {
701	        this.settingsResubmit = false;
702	        void this.saveSettings(event);
703	      }
704	    }
705	  }
706	
707	  protected async saveRole(event: Event): Promise<void> {
708	    event.preventDefault();
709	    if (this.savingRole) return;
710	    this.roleError.set(null);
711	    const sheet = this.session.sheetId();
712	    if (!sheet) return;
713	    const user = this.roleUser().trim();
714	    const role = this.role().trim();
715	    if (user === '') {
716	      this.roleError.set('Type a user name.');
717	      return;
718	    }
719	    if (!ROLES.includes(role as Role)) {
720	      this.roleError.set(`Choose a role: ${ROLES.join(' or ')}.`);
721	      return;
722	    }
723	    this.savingRole = true;
724	    try {
725	      const saved = await this.service.setRole(sheet, user, role as Role);
726	      if (this.session.sheetId() !== sheet) return;
727	      this.given.update((list) =>
728	        [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
729	      );
730	      this.roleUser.set('');
731	      this.role.set('');
732	    } catch {
733	      this.roleError.set('That role could not be set.');
734	    } finally {
735	      this.savingRole = false;
736	    }
737	  }
738	
739	  private async read(sheet: string): Promise<void> {
740	    try {
741	      const settings = await this.service.get(sheet);
742	      if (this.session.sheetId() === sheet) {
743	        this.show(settings);
744	        if (!this.limitChanged) this.limit.set(settings.clerkLimit ?? '');
745	        if (!this.floorChanged) this.floorInput.set(settings.floor);
746	        if (!this.termsChanged) this.termsInput.set(String(settings.terms));
747	        if (!this.latePctChanged) this.latePctInput.set(settings.latePct);
748	        if (!this.policyDateChanged) this.policyDateInput.set(settings.policyDate ?? '');
749	        if (!this.periodNumberingFromChanged) this.periodNumberingFromInput.set(settings.periodNumberingFrom ?? '');
750	      }
751	    } catch {
752	      // The settings could not be read; they show as none.
753	    }
754	  }
755	
756	  private show(settings: SheetSettings): void {
757	    this.clerkLimit.set(settings.clerkLimit);
758	    this.floor.set(settings.floor);
759	    this.terms.set(String(settings.terms));
760	    this.latePct.set(settings.latePct);
761	    this.policyDate.set(settings.policyDate);
762	    this.periodNumberingFrom.set(settings.periodNumberingFrom);
763	    this.given.set(settings.roles);
764	  }
765	}
766	import { HttpClient } from '@angular/common/http';
767	import { Injectable, inject } from '@angular/core';
768	import { firstValueFrom } from 'rxjs';
769	import { Session } from '../../core/session';
770	
771	/** A user's role on a sheet: every name is a clerk unless made a steward. */
772	export type Role = 'clerk' | 'steward';
773	
774	export const ROLES: readonly Role[] = ['clerk', 'steward'];
775	
776	export interface RoleGiven {
777	  user: string;
778	  role: Role;
779	}
780	
781	/** The floor a sheet starts with, in cents. */
782	export const FLOOR_CENTS = 100;
783	
784	/** The terms a sheet starts with, in days. */
785	export const TERMS_DAYS = 14;
786	
787	/** The late percent a sheet starts with. */
788	export const LATE_PCT = '0.00';
789	
790	export interface SheetSettings {
791	  /** The most a clerk may settle a claim for, with two decimals; null when there is no limit. */
792	  clerkLimit: string | null;
793	  /** The least a claim's live due can be, with two decimals. */
794	  floor: string;
795	  /** How many days after its date a claim is due by. */
796	  terms: number;
797	  /** The percent of its figure an overdue claim's due gains for every full 30 days it is overdue,
798	   *  with two decimals. */
799	  latePct: string;
800	  /** The date that decides how a claim's live figures round (YYYY-MM-DD); null when it is the
801	   *  sheet's today. */
802	  policyDate: string | null;
803	  /** The roles given on the sheet, by user name. */
804	  roles: RoleGiven[];
805	  /** The date (YYYY-MM-DD) from which a claim opened is numbered within its period; null when off. */
806	  periodNumberingFrom: string | null;
807	}
808	
809	// The settings of a sheet (its roles, its clerk limit, its floor, its terms, its late percent, its policy date and its period numbering from), read from and written to the server.
810	@Injectable({ providedIn: 'root' })
811	export class SettingsService {
812	  private readonly http = inject(HttpClient);
813	  private readonly session = inject(Session);
814	
815	  get(sheet: string): Promise<SheetSettings> {
816	    return firstValueFrom(
817	      this.http.get<SheetSettings>(`${this.url(sheet)}/settings`, { headers: this.session.headers() }),
818	    );
819	  }
820	
821	  /** A null value removes the limit. */
822	  setClerkLimit(sheet: string, value: string | null): Promise<SheetSettings> {
823	    return firstValueFrom(
824	      this.http.put<SheetSettings>(
825	        `${this.url(sheet)}/settings/clerk-limit`,
826	        { value },
827	        { headers: this.session.headers() },
828	      ),
829	    );
830	  }
831	
832	  setFloor(sheet: string, value: string): Promise<SheetSettings> {
833	    return firstValueFrom(
834	      this.http.put<SheetSettings>(`${this.url(sheet)}/settings/floor`, { value }, { headers: this.session.headers() }),
835	    );
836	  }
837	
838	  setTerms(sheet: string, value: string): Promise<SheetSettings> {
839	    return firstValueFrom(
840	      this.http.put<SheetSettings>(`${this.url(sheet)}/settings/terms`, { value }, { headers: this.session.headers() }),
841	    );
842	  }
843	
844	  setLatePct(sheet: string, value: string): Promise<SheetSettings> {
845	    return firstValueFrom(
846	      this.http.put<SheetSettings>(`${this.url(sheet)}/settings/late-pct`, { value }, { headers: this.session.headers() }),
847	    );
848	  }
849	
850	  /** A null value makes the policy date the sheet's today. */
851	  setPolicyDate(sheet: string, value: string | null): Promise<SheetSettings> {
852	    return firstValueFrom(
853	      this.http.put<SheetSettings>(
854	        `${this.url(sheet)}/settings/policy-date`,
855	        { value },
856	        { headers: this.session.headers() },
857	      ),
858	    );
859	  }
860	
861	  /** A null value turns period numbering off. */
862	  setPeriodNumberingFrom(sheet: string, value: string | null): Promise<SheetSettings> {
863	    return firstValueFrom(
864	      this.http.put<SheetSettings>(
865	        `${this.url(sheet)}/settings/period-numbering-from`,
866	        { value },
867	        { headers: this.session.headers() },
868	      ),
869	    );
870	  }
871	
872	  setRole(sheet: string, user: string, role: Role): Promise<RoleGiven> {
873	    return firstValueFrom(
874	      this.http.put<RoleGiven>(
875	        `${this.url(sheet)}/roles/${encodeURIComponent(user)}`,
876	        { role },
877	        { headers: this.session.headers() },
878	      ),
879	    );
880	  }
881	
882	  private url(sheet: string): string {
883	    return `/api/sheets/${encodeURIComponent(sheet)}`;
884	  }
885	}
