package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** A claim, with who opened it (null until opened) and whether it is bound to the figure it had
     * at its person's last statement; its amount, what was due on it when settled (null otherwise) and
     * the figure it is bound to (null when unbound or bound to no figure) are sent as text with two
     * decimals so they are never rounded on the way. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue,
            String openedBy, boolean stated, String statedDue, String corrects) {
        public static ClaimView of(Claim claim) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    text(claim.getSettledDue()), claim.getOpenedBy(), claim.isStated(), text(claim.getStatedDue()),
                    claim.getCorrects());
        }

        private static String text(BigDecimal figure) {
            return figure == null ? null : figure.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A claim's amount (with up to two decimals; negative on a correction), date (the sheet's today
     * when left out), note (may be empty) and, on a correction, the number of the claim it corrects. */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Size(max = 120) String corrects) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        /** The number named, trimmed; null when none is. */
        String correctsValue() {
            return corrects == null || corrects.isBlank() ? null : corrects.trim();
        }
    }

    /** Why a steward rejects a PENDING claim: one word, as it is written into the audit. */
    public record RejectRequest(@NotNull @Pattern(regexp = "\\s*\\S{1,200}\\s*") String reason) {
    }

    /** The person a claim is moved to, by id. */
    public record ReassignRequest(@NotNull Long personId) {
    }

    /** The claims a bulk change is asked of, by id. */
    public record BulkRequest(@NotNull @Size(max = 1000) List<@NotNull Long> claimIds) {
    }

    /** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Claim {
  id: number;
  personId: number;
  /** The amount with two decimals, as text (e.g. "10.50"). */
  amount: string;
  /** YYYY-MM-DD */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when it is opened (sheet-wide, e.g. "3", or within its
   *  period, e.g. "P1-2", or "X-1" in no period); null while DRAFT. */
  number: string | null;
  /** What was due on the claim when it was settled, with two decimals; null otherwise, and when its
   *  person's grade had no rate then. */
  settledDue: string | null;
  /** The user who opened the claim; null until it is opened. */
  openedBy: string | null;
  /** Whether the claim is bound to the figure it had at its person's last statement. */
  stated: boolean;
  /** The figure it is bound to, with two decimals; null while unbound, and when it had no figure
   *  (no rate) then. */
  statedDue: string | null;
  /** On a correction (a claim with a negative amount), the number of the SETTLED claim of the same
   *  person it corrects; null on any other claim. */
  corrects: string | null;
}

/** Added as DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it PENDING
 *  until a steward approves it (SETTLED) or rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim
 *  can be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A status change asked of a claim. */
export type ClaimAction = 'open' | 'settle' | 'approve' | 'reject' | 'void';

/** Whether a claim in this status counts toward what is claimed and due. */
export function counts(claim: Claim): boolean {
  return isOpen(claim) || claim.status === 'SETTLED';
}

/** Whether a claim is still open: OPEN, or PENDING, which is handled like OPEN (it goes overdue,
 *  bears the late charge and leaves the totals while its person is on hold). */
export function isOpen(claim: Claim): boolean {
  return claim.status === 'OPEN' || claim.status === 'PENDING';
}

/** The date (YYYY-MM-DD) a claim is due by: its date plus the sheet's terms, in days. */
export function dueByOf(claim: Claim, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: OPEN or PENDING, and due by a date before the sheet's today. */
export function overdue(claim: Claim, terms: number, today: string | null): boolean {
  return isOpen(claim) && today !== null && dueByOf(claim, terms) < today;
}

/** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
export interface BulkOpened {
  opened: number;
  refused: number;
  claims: Claim[];
}

export interface ClaimFields {
  const due = grade === null ? null : dueCents(cents(claim.amount), rateOn(rates, grade, claim.date), roundsHalfUp(claim, rounding));
  return due === null ? null : isCorrection(claim) ? due : Math.max(due, floorCents);
}

/** What a late charge is worked from: the sheet's terms, in days, its today, and its late percent
 *  with two decimals. */
export interface Lateness {
  terms: number;
  today: string | null;
  latePct: string;
}

/** The late charge on a claim whose figure is figureCents, in cents: the late percent of that figure
 *  for every full 30 days the claim is overdue (OPEN or PENDING, and past its due-by on the sheet's today),
 *  rounded like the claim's due; 0 on any other claim, and on a correction. A statement never binds it; settling fixes it in. */
export function lateChargeCents(claim: Claim, figureCents: number, late: Lateness, rounding: Rounding): number {
  if (!isOpen(claim) || late.today === null || isCorrection(claim)) return 0;
  const days = (Date.parse(late.today) - Date.parse(dueByOf(claim, late.terms))) / 86_400_000;
  const periods = Math.max(0, Math.floor(days / 30));
  return dueCents(figureCents * periods, late.latePct, roundsHalfUp(claim, rounding)) ?? 0;
}

/** What is due on a claim as it shows and totals, in cents: its figure (see claimDueCents) plus its
 *  late charge; null when it has no figure. */
export function claimShownCents(
  claim: Claim,
